out=r/'docs/learning/gravity-angle-preview';out.mkdir(parents=True,exist_ok=True)
raw=r/'artifacts/attitude-preview/20261030T221524/serial-original.log'
a=np.array([[float(v) for v in line.split(',')[1:]] for line in raw.read_text(errors='replace').splitlines() if line.startswith('D,') and len(line.split(','))==13])
t=(a[:,0]-a[0,0])/1000
fig,axs=plt.subplots(2,1,figsize=(10,5.5),sharex=True,layout='constrained')
axs[0].plot(t,a[:,7],label='Roll',color='#06754a');axs[0].plot(t,a[:,8],label='Pitch',color='#c65d17')
axs[0].axhspan(80,90,color='#f8b85a',alpha=.2);axs[0].axhspan(-90,-80,color='#f8b85a',alpha=.2)
axs[0].set_ylabel('Gravity angles (deg)');axs[0].legend(ncol=2)
axs[1].plot(t,np.linalg.norm(a[:,1:4],axis=1),color='#176b89');axs[1].axhline(9.80665,ls='--',color='#555',label='Reference g')
axs[1].set_ylabel('Acceleration norm (m/s²)');axs[1].set_xlabel('MCU sequence / nominal 1000 Hz (s)');axs[1].legend()
for ax in axs:ax.grid(alpha=.2)
fig.suptitle('Actual ESP32-S3 recording | 1166 diagnostic rows | no independent pose reference')
fig.savefig(out/'actual-trace.png',dpi=160);plt.close(fig)
theta=np.linspace(0,89.9,500);den=np.cos(np.deg2rad(theta));sensitivity=1/np.maximum(den,.001)
fig,axs=plt.subplots(1,2,figsize=(10,3.5),layout='constrained')
axs[0].plot(theta,den,color='#06754a');axs[0].set(xlabel='Pitch (deg)',ylabel='sqrt(ay² + az²) / g',title='Static gravity model')
axs[1].semilogy(theta,sensitivity,color='#c65d17');axs[1].set(xlabel='Pitch (deg)',ylabel='Relative roll sensitivity ~ 1 / |cos(pitch)|',title='Illustration, not measured noise')
for ax in axs:ax.grid(alpha=.2)
fig.savefig(out/'geometry.png',dpi=160);plt.close(fig)
examples=[
("fig.suptitle('Calibrated gravity tilt preview - motors disabled')","fig is the Figure object; . selects its method; suptitle is the whole-figure title. Parentheses call it. Quotes delimit a string. The ASCII hyphen avoids the previously corrupted dash. It is not subtraction inside this string. The title change does not alter sensor data."),
("axes[0].set_ylim(-180, 180)","axes is the list/array of plot panels; [0] selects the first (Python indexes start at zero). .set_ylim calls the vertical-limit method. -180 is a negative number; comma separates lower and upper arguments. The closing parenthesis ends the call. Units are degrees because those are the plotted values; the method does not convert units. Fixed limits prevent tiny resting noise from being enlarged by automatic vertical scaling."),
("status = axes[0].text(0.01, 0.98, 'Waiting for data', transform=axes[0].transAxes, va='top', fontsize=9)","= assigns the returned Text object to status. The first two arguments locate it at 1% of the panel width and 98% of its height because transform=axes[0].transAxes selects panel-relative coordinates. Decimal points form floating-point numbers. Keyword=value arguments name options: va='top' anchors the top of the text at that position; fontsize=9 sets point size. This text moves with the panel, not with the data scale."),
("roll, pitch = float(fields[8]), float(fields[9])","fields is the comma-split serial record, including 'D' at index0. [8] and [9] select roll and pitch, as defined by the firmware D record. float(...) converts each numeric string to a floating-point number. The comma on each side makes a pair: Python assigns the first converted value to roll and the second to pitch. This is not a new angle estimator."),
("norm = sum(float(fields[i])**2 for i in (2, 3, 4))**0.5","fields[2:5] are ax, ay, az in m/s² (the slice is explanatory; the actual code uses the tuple (2,3,4)). for i in (...) generates one term per selected index. ** means exponentiation: each acceleration is squared; sum adds all three squares; **0.5 takes their square root. Thus norm = sqrt(ax² + ay² + az²). Parentheses group operations and call functions; dots in 0.5 denote a decimal, unlike the method-access dot. No vector direction survives in this norm."),
("warning = 'Near vertical pitch: roll is poorly observable from gravity' if abs(pitch)>80 else 'Gravity tilt only - axes provisional'","This is a conditional expression: choose the first string if the condition is true, otherwise choose the string after else. abs removes the sign of pitch. > tests strictly greater than80degrees; it does not assign a value. 80 is a display-warning threshold chosen before the singularity, not a calibrated physical limit and not a flight control setting."),
("if abs(norm-9.80665)>1.5: warning += ' | Acceleration disturbance'","if tests a condition; : introduces its body (here on the same line). norm-9.80665 subtracts reference gravity in m/s². abs makes deviations in either direction positive. >1.5 compares to a heuristic 1.5m/s² tolerance. += appends text to the existing warning string; it does not add acceleration. The vertical bar is a visual separator inside the quotes. This is only a suspicion indicator: some motion has norm near g, and calibration error can also alter the norm."),
("status.set_text(warning)","Call the saved Text object's set_text method with the selected message. No Serial command is sent and no angle value is replaced."),
("for buf, v in zip(history, [time.monotonic()-started, roll, pitch, float(fields[12])*57.295779513]): buf.append(v)","for loops through paired items. zip pairs the four history buffers with four values in the same order. [] constructs that list. time.monotonic() is a host clock unaffected by wall-clock corrections; subtracting started gives receive-time seconds. fields[12] is body Z angular velocity in rad/s; *57.295779513 converts it to deg/s (180/pi). Each deque receives one value through .append(v); its maxlen=300 keeps only the latest300 rows. This rate is a body Z rate, not generally the derivative of Euler yaw at large tilt. The timestamp is host receipt time, not the sensor's sampling instant."),
("for ax in axes: ax.relim(); ax.autoscale_view()\naxes[0].set_ylim(-180, 180)","The for iterates panels. : starts the body; ; separates two statements on the compact line. relim recomputes the data bounds; autoscale_view uses those bounds for eligible axes. The next line resets the angle limits after that update, while time and the lower rate panel may still autoscale. The fixed limits help visual interpretation; they do not suppress noise, clipping or Euler wrapping.")]
parts=''.join('<details><summary>'+html.escape(code.split('\n')[0])+'</summary><pre><code>'+html.escape(code)+'</code></pre><p>'+html.escape(explain)+'</p></details>' for code,explain in examples)
